guidance.correct_example:
def read_file(a_path: str) -> Result[str]:
    try:
        with open(a_path) as f:
            content = f.read()
    except FileNotFoundError as e:
        return Result.failure(f'File not found: {a_path}: {e}')
    return Result.success(content)

guidance.incorrect_example:
def read_file(a_path: str) -> Result[str]:
    f = open(a_path)
    content = f.read()
    return Result.success(content)
